<?php use App\Core\Csrf; ?>
<div class="page-heading"><div><p class="eyebrow">Monitoring</p><h1>Student attendance</h1><p>Record daily attendance for the students currently enrolled in a section.</p></div><a class="button" href="<?=e(url('/attendance/teachers'))?>">Teacher attendance</a></div>
<form method="get" class="filter-bar attendance-filter"><label>Section<select required name="section_id"><option value="">Select a section</option><?php foreach($sections as $s):?><option value="<?=$s['id']?>" <?=$sectionId===(int)$s['id']?'selected':''?>><?=e($s['school_year'].' — '.$s['grade_level'].' '.$s['name'])?></option><?php endforeach;?></select></label><label>Date<input type="date" name="date" required value="<?=e($date)?>"></label><button class="button primary">Load attendance</button></form>
<?php if($sectionId):?><form method="post" action="<?=e(url('/attendance/students'))?>"><?=Csrf::field()?><input type="hidden" name="section_id" value="<?=$sectionId?>"><input type="hidden" name="date" value="<?=e($date)?>"><section class="card table-card"><div class="table-heading"><div><h2><?=e($date)?></h2><small><?=$session?'Existing attendance session':'New attendance session'?></small></div><?php if($canRecord):?><button type="button" class="button small" data-mark-present>Mark all present</button><?php endif;?></div><table class="attendance-table"><thead><tr><th>Student</th><th>Status</th><th>Arrival</th><th>Remarks</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><strong><?=e($s['last_name'].', '.$s['first_name'])?></strong><br><small><?=e($s['student_no'])?></small></td><td><select name="attendance[<?=$s['id']?>][status]" <?=$canRecord?'':'disabled'?> class="status-select"><?php foreach($statuses as $status):?><option value="<?=$status?>" <?=$s['attendance_status']===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></td><td><input type="time" name="attendance[<?=$s['id']?>][arrival_time]" value="<?=e(substr((string)$s['arrival_time'],0,5))?>" <?=$canRecord?'':'disabled'?>></td><td><input name="attendance[<?=$s['id']?>][remarks]" value="<?=e($s['remarks'])?>" maxlength="500" <?=$canRecord?'':'disabled'?>></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="4" class="empty">No active students are enrolled in this section.</td></tr><?php endif;?></tbody></table></section><?php if($canRecord&&$students):?><div class="sticky-actions"><button class="button primary">Save student attendance</button></div><?php endif;?></form><?php endif;?>
<script>document.querySelector('[data-mark-present]')?.addEventListener('click',()=>document.querySelectorAll('.status-select').forEach(x=>x.value='present'));</script>
